CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261119092537_InitialPostgreSqlCreate') THEN
    CREATE TABLE "Departments" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(100) NOT NULL,
        "Code" character varying(30) NOT NULL,
        "Description" character varying(500),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Departments" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261119092537_InitialPostgreSqlCreate') THEN
    CREATE TABLE "Categories" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(100) NOT NULL,
        "Description" character varying(500),
        "DepartmentId" integer NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Categories" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Categories_Departments_DepartmentId" FOREIGN KEY ("DepartmentId") REFERENCES "Departments" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261119092537_InitialPostgreSqlCreate') THEN
    CREATE TABLE "Users" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "FullName" character varying(150) NOT NULL,
        "Email" character varying(150) NOT NULL,
        "RegistrationNumber" character varying(50),
        "AcademicProgram" character varying(150),
        "PasswordHash" text NOT NULL,
        "Role" character varying(30) NOT NULL,
        "DepartmentId" integer,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Users" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Users_Departments_DepartmentId" FOREIGN KEY ("DepartmentId") REFERENCES "Departments" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261119092537_InitialPostgreSqlCreate') THEN
    CREATE TABLE "IssueTypes" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Name" character varying(150) NOT NULL,
        "CategoryId" integer NOT NULL,
        "DefaultPriority" character varying(30) NOT NULL,
        "SlaHours" integer NOT NULL,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_IssueTypes" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_IssueTypes_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261119092537_InitialPostgreSqlCreate') THEN
    CREATE TABLE "Complaints" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "TrackingCode" character varying(30) NOT NULL,
        "Title" character varying(200) NOT NULL,
        "Description" text NOT NULL,
        "Location" character varying(150),
        "CategoryId" integer NOT NULL,
        "DepartmentId" integer NOT NULL,
        "IssueTypeId" integer,
        "Priority" character varying(30) NOT NULL,
        "Status" character varying(30) NOT NULL,
        "IsAnonymous" boolean NOT NULL,
        "StudentId" integer NOT NULL,
        "Rating" integer,
        "RatingFeedback" text,
        "ReopenCount" integer NOT NULL,
        "ReopenReason" text,
        "RowVersion" bytea NOT NULL DEFAULT (substring(decode(md5(random()::text), 'hex') from 1 for 8)),
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        "ResolvedAtUtc" timestamp with time zone,
        CONSTRAINT "PK_Complaints" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Complaints_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Complaints_Departments_DepartmentId" FOREIGN KEY ("DepartmentId") REFERENCES "Departments" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Complaints_IssueTypes_IssueTypeId" FOREIGN KEY ("IssueTypeId") REFERENCES "IssueTypes" ("Id") ON DELETE SET NULL,
        CONSTRAINT "FK_Complaints_Users_StudentId" FOREIGN KEY ("StudentId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

