        "FileSize" bigint NOT NULL,
        "FileData" bytea NOT NULL,
        "UploadedAtUtc" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_ComplaintAttachments" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_ComplaintAttachments_Complaints_ComplaintId" FOREIGN KEY ("ComplaintId") REFERENCES "Complaints" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

